mapper.update:
UPDATE agent_session
SET persona_id = #{personaId}
WHERE id = #{id}

UPDATE agent_session
SET window_level = #{windowLevel}
WHERE id = #{id}

UPDATE agent_session
SET emotion = #{emotion}
WHERE id = #{id}

UPDATE agent_session
SET summary_entry_id = #{summaryEntryId}
WHERE id = #{id}

UPDATE agent_session
SET lifecycle = 'DESTROYED'
WHERE platform = #{platform}
  AND bot_id = #{botId}
  AND group_id = #{groupId}

mapper.select:
SELECT kind, occurred_at AS occurredAt
FROM transcript_entry
WHERE kind IN ('user', 'assistant', 'summary')
AND occurred_at >= #{from}
AND occurred_at <= #{to}
AND group_id = #{groupId}
ORDER BY occurred_at ASC
